-- ============================================================================
-- DDISA Grantee Directory — seed data
-- ----------------------------------------------------------------------------
-- GENERATED FILE — do not edit by hand. Regenerate with: npm run build:seed
--
-- Inserts the 46 Cohort 1 organisations from the embedded directory
-- source, plus 111 Type of CSO rows, 107 offerings and 80
-- social links. Safe to re-run: organisations are upserted by slug and the
-- child rows for these organisations are rebuilt from the source of truth
-- (hand-edited profile data for these 46 organisations will be overwritten).
--
-- Logo/photo paths point at the storage buckets; run `npm run upload:assets`
-- afterwards so those objects exist, otherwise the profile images will 404.
--
-- Run after supabase/schema.sql. If Supabase reports a missing column, re-run
-- supabase/schema.sql first (it is idempotent), then run this file again.
-- ============================================================================

begin;

-- schema.sql revisions after the original release added logo_background;
-- create it here if the database was set up from an older schema file.
alter table public.organisations
  add column if not exists logo_background text not null default '';

-- 1. Organisations -----------------------------------------------------------
insert into public.organisations (
  slug, name, country, region, cohort, summary, description,
  collaboration, focus_areas, matched, logo_path, photo_path,
  photo_alt, logo_background, publication_status
)
values
  ('association-for-digital-citizenship-education-digieducivic-and-kubaarucheck', 'Association for Digital Citizenship Education  (DigiEduCivic) and KubaaruCheck', 'Cameroon', 'Central Africa', 'Cohort 1', 'Trains young people in media and information literacy and advances digital citizenship in Cameroon.', 'The Association for Digital Citizenship Education is an organization that advocates for digital innovation and the education of young people in media and information literacy.', 'Collaboration interests have not yet been confirmed.', array['Digital rights', 'Digital safety & online security', 'Countering misinformation & disinformation', 'Access to information & digital inclusion', 'Gender justice & technology'], true, 'organisation-logos/logos/association-for-digital-citizenship-education-digieducivic-and-kubaarucheck.webp', '', '', '', 'published'),
  ('advokc-foundation-for-promotion-of-good-governance-accountability', 'AdvoKC Foundation For Promotion Of Good Governance & Accountability', 'Nigeria', 'West Africa', 'Cohort 1', 'Uses civic technology, data and advocacy to help Nigerian citizens track public commitments and demand accountable governance.', 'AdvoKC Foundation is a civic-tech and advocacy organisation focused on strengthening accountability, democratic governance, and public service delivery in Nigeria. We design and deploy tools such as promise trackers and legislative monitoring platforms to track commitments made by elected officials and assess their performance. Through data-driven advocacy, community engagement, and strategic communications, we empower citizens with accessible information to demand transparency and hold leaders accountable. Our work also involves policy research, media campaigns, and partnerships that amplify citizen voices and promote responsive governance', 'Collaboration interests have not yet been confirmed.', array['Transparency & open data'], true, 'organisation-logos/logos/advokc-foundation-for-promotion-of-good-governance-accountability.webp', '', '', '', 'published'),
  ('centre-for-climate-accountability-and-transportation', 'Centre for Climate Accountability and Transportation', 'Uganda', 'Eastern Africa', 'Cohort 1', 'Advances climate action and inclusive governance through civic engagement, digital literacy and its CIV-CON citizen reporting platform.', 'Centre for Climate Accountability and Transportation (CCAT) is a youth-led civic organisation advancing climate action, accountability, and inclusive development. We empower communities through civic engagement, digital literacy trainings, and advocacy on climate change, gender-based violence (GBV and TFGBV), and sustainable transportation. Our work strengthens citizen participation, promotes transparency, and equips young people and vulnerable groups with skills and tools to engage in decision-making. Through our innovation, CIV-CON, we bridge the gap between citizens and leaders using digital platforms, enhancing access to information, reporting mechanisms, and responsive governance.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Transparency & open data', 'Electoral integrity & voter education', 'Digital rights', 'Digital safety & online security', 'Countering misinformation & disinformation', 'Access to information & digital inclusion', 'Gender justice & technology', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/centre-for-climate-accountability-and-transportation.webp', '', '', '', 'published'),
  ('alive-albinism-initiative', 'Alive Albinism Initiative', 'Zimbabwe', 'Southern Africa', 'Cohort 1', 'Promotes the rights and inclusion of people with albinism and other disabilities through advocacy, digital skills and community dialogue.', 'Alive Albinism Initiative (AAI) works to promote the rights, dignity, and inclusion of persons with albinism and other persons with disabilities in Zimbabwe. The organisation focuses on advocacy, civic engagement, and digital inclusion to address stigma, discrimination, and barriers to participation. AAI implements community-based programmes, including awareness campaigns, digital literacy training, and stakeholder dialogues, to empower marginalized groups. Using inclusive and human-centred approaches, AAI leverages technology and partnerships to amplify voices, improve access to information, and strengthen participation in social, economic, and democratic processes, particularly in rural and underserved communities.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Access to information & digital inclusion', 'Intersectional disability inclusion'], true, 'organisation-logos/logos/alive-albinism-initiative.webp', '', '', '', 'published'),
  ('advocacy-for-youth-and-vulnerable-development-initiative-ayvdi', 'Advocacy for Youth and Vulnerable Development Initiative (AYVDi)', 'Nigeria', 'West Africa', 'Cohort 1', 'Builds digital literacy, civic participation and resilience to misinformation among young people and underserved Nigerian communities.', 'Advocacy for Youth and Vulnerable Development Initiative (AYVDi) works at the intersection of digital rights, civic engagement, and grassroots community development in Nigeria, with a focus on empowering young people and underserved populations. We design and implement community-based programmes that promote digital literacy, counter misinformation, and strengthen citizens’ ability to participate meaningfully in democratic processes. Through school outreaches, community dialogues, and digital advocacy campaigns, we have reached over 11,000 students and community members across underserved communities in Ilorin, Ogbomoso. Our work bridges the gap between offline communities and digital opportunities, equipping individuals with the knowledge and tools to safely navigate the digital space, access information, and engage in civic life.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Electoral integrity & voter education', 'Countering misinformation & disinformation'], true, 'organisation-logos/logos/advocacy-for-youth-and-vulnerable-development-initiative-ayvdi.webp', '', '', '', 'published'),
  ('community-advocacy-and-awareness-trust-crawn-trust', 'Community Advocacy and Awareness Trust-CRAWN Trust', 'Kenya', 'Eastern Africa', 'Cohort 1', 'Advances gender equity in Kenya through civic education, leadership, policy advocacy and a national women''s rights resource centre.', 'CRAWN Trust works as a change catalyst advancing gender equity by championing the inclusion of women in political, social, economic, and cultural spheres. Through innovative advocacy and civic education rooted in the Constitution of Kenya 2010, the organization empowers women and girls to claim their rights and actively shape decision making spaces. Its work spans transformative leadership, sustainable livelihoods and climate resilience, strategic partnerships, research driven policy advocacy, and institutional growth. Notably, CRAWN hosts a Gender Resource Center featuring a directory of over 1,400 women’s rights organizations, seeking to strengthen collective action. By amplifying voice, agency, and opportunity, we are driving bold, community led transformation across Kenya.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Countering misinformation & disinformation', 'Access to information & digital inclusion'], true, 'organisation-logos/logos/community-advocacy-and-awareness-trust-crawn-trust.webp', '', '', '', 'published'),
  ('associa-o-empoderando-mo-ambique-aem', 'Associação Empoderando Moçambique (AEM)', 'Mozambique', 'Southern Africa', 'Cohort 1', 'Develops locally relevant digital platforms and social innovations that improve health, economic opportunity and public services in Mozambique.', 'AEM is a social innovation studio dedicated to driving sustainable development across Mozambique through context-appropriate technology solutions. Our mission is to equip Mozambicans with the tools, knowledge, and resources they need to overcome systemic challenges and improve their socioeconomic conditions. We incubate and develop initiatives across multiple sectors, maintaining a portfolio of high-impact digital platforms. Through this integrated approach, we target interconnected socioeconomic challenges, focusing on solutions that generate measurable improvements in health outcomes, economic opportunity, and quality of life for the most vulnerable Mozambicans. ', 'Collaboration interests have not yet been confirmed.', array['Transparency & open data', 'Access to information & digital inclusion', 'Gender justice & technology', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/associacao-empoderando-mocambique-aem.webp', '', '', '', 'published'),
  ('black-girl-magic', 'Black Girl Magic', 'Zimbabwe', 'Southern Africa', 'Cohort 1', 'Supports young women in Zimbabwe to build creative expression, leadership and digital media skills.', 'Black Girl Magic is a Harare-based initiative supported through Magamba''s fiscal sponsorship. It creates opportunities for young women in Zimbabwe to express themselves creatively, develop leadership skills and use digital media to share their stories. Its work focuses on building confidence and practical media skills so that young women can participate more fully in public life.', 'Collaboration interests have not yet been confirmed.', array['Gender justice & technology', 'Youth civic engagement & digital technology', 'Access to information & digital inclusion'], true, 'organisation-logos/logos/black-girl-magic.webp', '', '', '', 'published'),
  ('bo-foundation-for-inclusive-media-bofim', 'BO Foundation for Inclusive Media (BOFIM)', 'Nigeria', 'West Africa', 'Cohort 1', 'Promotes inclusive media in South West Nigeria by amplifying marginalised voices and advocating for women, children and people with disabilities.', 'The BO Foundation for Inclusive Media (BOFIM) is a women and youth-led not-for-profit organisation (RN7509147) dedicated to promoting inclusive media as a means of social change in Nigeria, particularly in the South West. Our goal is to create a society where the media fosters unity, amplifies the voices of marginalised groups, and advocates for the rights and well-being of everyone, especially persons with disabilities, women, and children.
Since our establishment in May 2024, BOFIM has combined capacity building, advocacy, and practical interventions to drive impact.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Electoral integrity & voter education', 'Digital rights', 'Digital safety & online security', 'Access to information & digital inclusion', 'Gender justice & technology', 'Intersectional disability inclusion'], true, 'organisation-logos/logos/bo-foundation-for-inclusive-media-bofim.webp', '', '', '', 'published'),
  ('global-tech-inclusion-network-gtin', 'Global Tech Inclusion Network (GTIN)', 'Uganda', 'Eastern Africa', 'Cohort 1', 'Uses technology and data to expand digital inclusion, advance digital rights and strengthen civic participation in Uganda.', 'Global Tech Inclusion Network (GTIN) is a feminist, youth-led, tech-centred nonprofit organization advancing gender equality, digital inclusion, internet access, digital rights and climate justice through technology and data-driven innovation. We empower women and marginalized communities with equitable access to the internet, skills, and tools to participate fully in the digital economy.

A key focus of our work is strengthening civic engagement, transparency, and accountability. We design and deploy innovative digital platforms and community-driven solutions that enable citizens to access information, monitor service delivery, and engage decision-makers. By centering inclusivity and local voices, we promote digital democracy and ensure communities not only use technology, but shape it to drive social justice and responsive governance.
', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Transparency & open data', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/global-tech-inclusion-network-gtin.webp', '', '', '', 'published'),
  ('brain-builders-youth-development-initiative-bbydi', 'Brain Builders Youth Development Initiative (BBYDI)', 'Nigeria', 'West Africa', 'Cohort 1', 'Equips young Nigerians to track public projects, report digital gender-based violence and build digital literacy and online safety skills.', 'Brain Builders Youth Development Initiative (BBYDI) is a youth-led, nonpartisan civic organisation advancing inclusive governance and democratic participation in Nigeria. We equip young people and marginalised communities, especially women with the tools to engage in civic processes, demand accountability, and exercise digital rights. Our work spans several pillars including: accountability (through YouthGovTracka, monitoring public projects), gender justice and technology (through HerSafeSpace, strengthening digital GBV reporting and response for young women) and digital literacy (including AI literacy and online safety). Through data-driven advocacy, civic technology, and community engagement, we bridge the gap between citizens and government while promoting transparency, gender justice, and active citizenship.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Digital rights', 'Digital safety & online security', 'Gender justice & technology'], true, 'organisation-logos/logos/brain-builders-youth-development-initiative-bbydi.webp', '', '', '', 'published'),
  ('imagined-spaces-initiative', 'Imagined Spaces Initiative', 'Uganda', 'Eastern Africa', 'Cohort 1', 'Uses research, digital rights advocacy and community technology to help marginalised communities participate safely online and influence decisions in Uganda.', 'Reclaiming Spaces Initiative is a civic-tech and digital rights think tank based in Uganda, focused on advancing digital inclusion, civic engagement, and human rights. We leverage technology to empower marginalized communities with the tools, knowledge, and platforms needed to safely participate in digital spaces and influence decision-making. Our work spans digital rights advocacy, community connectivity, research, and innovation, including the development of tech-driven solutions to address challenges such as GBV and limited access to information.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Digital rights', 'Digital safety & online security', 'Access to information & digital inclusion', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/imagined-spaces-initiative.webp', '', '', '', 'published'),
  ('bustop-tv-trust', 'Bustop TV Trust', 'Zimbabwe', 'Southern Africa', 'Cohort 1', 'Uses satire, comedy and participatory media to make civic issues accessible and encourage democratic participation in Zimbabwe.', 'Bustop TV is a youth-led digital media collective in Zimbabwe that harnesses satire, comedy, and creative storytelling to advance civic engagement and democratic participation. Through viral skits, street interviews, and social commentary, people''s bus shows, podcasts, we make complex political and social issues accessible, sparking dialogue and mobilizing citizens. Our work promotes freedom of expression, transparency, and accountability while amplifying marginalized voices, especially youth and women. By leveraging digital platforms, Bustop TV innovates civic communication, transforming humor into a powerful tool for social change and inclusive democracy.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement'], true, 'organisation-logos/logos/bustop-tv-trust.png', '', '', '', 'published'),
  ('civic-verse-policy-education-project-ltd-gte-poliz', 'Civic-Verse Policy Education Project Ltd/Gte (PoliZ)', 'Nigeria', 'West Africa', 'Cohort 1', 'Makes Nigerian public policy and governance easier for young people to understand and engage with.', 'Civic-Verse Policy Education Project, known as PoliZ, is an Abuja-based civic media and policy education organisation. It makes public policy and governance in Nigeria simpler to understand and more accessible to young people through plain-language explainers, analysis and youth-focused engagement. Its work aims to build informed citizens who can follow government decisions, understand how policy affects their lives and participate more confidently in public debate.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Transparency & open data', 'Access to information & digital inclusion', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/civic-verse-policy-education-project-ltd-gte-poliz.png', '', '', '', 'published'),
  ('ingoverse-tech-hub-cbo', 'Ingoverse Tech Hub CBO', 'Kenya', 'Eastern Africa', 'Cohort 1', 'Builds digital and civic skills among young people in Kakamega County, Kenya, through training, mentorship and community innovation.', 'Ingoverse is a youth-led community innovation organization based in Kakamega, Kenya. We work to equip young people and underserved communities with practical digital skills, civic participation tools, and innovation support that help them address local challenges. Our work focuses on digital inclusion, youth empowerment, climate and community resilience, and the use of technology for public problem-solving. Through training, mentorship, community programs, and collaborative projects, we help young people become active contributors in shaping their communities, improving livelihoods, and engaging more effectively in social, economic, and civic life.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Transparency & open data', 'Electoral integrity & voter education', 'Digital rights', 'Digital safety & online security', 'Countering misinformation & disinformation', 'Access to information & digital inclusion', 'Gender justice & technology', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/ingoverse-tech-hub-cbo.webp', '', '', '', 'published'),
  ('connected-youth-for-accountability-peace-and-development-initiative-yapd4africa', 'Connected Youth for Accountability, Peace and Development Initiative (YAPD4Africa)', 'Nigeria', 'West Africa', 'Cohort 1', 'Strengthens grassroots civic participation and local governance in Nigeria through technology, citizen engagement and community leadership.', 'Our primary mission is to build strong people and sustainable communities by empowering them with the accurate knowledge and skills needed to advocate for their rights and lead local development.

With over eight years of experience in grassroots communities, we possess a unique combination of expertise in citizen engagement and local governance. Our primary work exists at the intersection of civic participation, technology and democratic governance. 

By combining professional skills in project management, technical design and social leadership, we are uniquely positioned to implement this DDISA project.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Electoral integrity & voter education'], true, 'organisation-logos/logos/connected-youth-for-accountability-peace-and-development-initiative-yapd4africa.webp', '', '', '', 'published'),
  ('defenders-protection-initiative', 'Defenders Protection Initiative', 'Uganda', 'Eastern Africa', 'Cohort 1', 'Protects rights defenders, activists and journalists in Uganda through digital security, emergency response and practical safety support.', 'Defenders Protection Initiative (DPI) is a Ugandan civil society organisation working to protect and strengthen the safety, resilience, and civic participation of human rights defenders, activists, journalists, and grassroots organisations. We focus on digital & physical security, emergency response, and capacity-building, supporting communities at risk including women, LGBTQI+ persons, and rural and marginalised groups. DPI delivers practical interventions such as digital security clinics, rapid response support, and tools that help organisations identify and reduce their exposure to digital threats. Our work aims to ensure that vulnerable communities can safely engage in civic space and digital platforms without fear of surveillance, harassment, or compromise.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Digital rights', 'Digital safety & online security', 'Access to information & digital inclusion'], true, 'organisation-logos/logos/defenders-protection-initiative.webp', '', '', '', 'published'),
  ('connecting-villages-for-sustainable-development-initiative', 'Connecting Villages for Sustainable Development Initiative', 'Nigeria', 'West Africa', 'Cohort 1', 'Empowers rural communities in Northern Nigeria through civic accountability, climate education, youth leadership and sustainable development programmes.', 'Connecting Villages Initiative (CVI) is a youth-led organization empowering young people, women, and girls in rural and underserved communities in Northern Nigeria to drive their own sustainable development. Our work focuses on democracy and governance, climate resilience, education, and human rights, using community mobilization, capacity building, and policy advocacy. We connect communities to opportunities, build practical skills, and create inclusive platforms for participation and leadership. Through initiatives like grassroots accountability projects and climate education clubs, we equip communities to improve livelihoods, engage institutions, and lead local solutions. CVI adopts a bottom-up approach, ensuring communities are not just beneficiaries but active drivers of inclusive and sustainable development.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Transparency & open data', 'Electoral integrity & voter education', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/connecting-villages-for-sustainable-development-initiative.webp', '', '', '', 'published'),
  ('keiyo-women-trust', 'Keiyo Women Trust', 'Kenya', 'Eastern Africa', 'Cohort 1', 'A women-led Kenyan organisation advancing the rights and economic opportunities of indigenous women and girls and challenging harmful norms.', 'Keiyo Women Trust (KWT) is a not for profit making organization, based in Kenya working towards improving and changing the lives of vulnerable girls and young women in Kenya.

As an indigenous women-led organization, KWT champions the rights of women and girls among indigenous communities through strengthening and supporting their capacity and agency to influence policies, decision making processes, and address harmful cultural practices while promoting positive culture

We focus on addressing structural barriers that prevent or limit women and girls’ exercise of their economic rights as well as to challenge social norms that continue to undermine their role and stifle their potential to thrive.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Access to information & digital inclusion'], true, 'organisation-logos/logos/keiyo-women-trust.webp', '', '', '', 'published'),
  ('digital-content-creators-alliance-t-a-community-podium', 'Digital Content Creators Alliance t/a Community Podium', 'Zimbabwe', 'Southern Africa', 'Cohort 1', 'Trains storytellers and produces participatory media that amplify marginalised voices and strengthen civic dialogue in Zimbabwe.', 'Community Podium is a non-profit participatory media organisation that empowers content creators and amplifies marginalized voices. We create inclusive platforms both online and offline where communities can share their stories, access information, and engage in civic dialogue. Our work includes training, content production, community-centered reporting, and research-driven advocacy. By strengthening access to information and supporting local storytellers, we enable communities to reclaim their voice and participate meaningfully in public life.
', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Access to information & digital inclusion'], true, 'organisation-logos/logos/digital-content-creators-alliance-t-a-community-podium.webp', '', '', '', 'published'),
  ('dailyviz263', 'DailyViz263', 'Zimbabwe', 'Southern Africa', 'Cohort 1', 'Turns public data and civic issues into accessible visual stories for Zimbabwean audiences.', 'DailyViz263 is a Harare-based digital media project that uses data visualisation, graphics and social media to make civic information clearer and more engaging. It translates public data and current issues into accessible visual stories that help Zimbabweans understand developments affecting their communities and take part in public conversations.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Access to information & digital inclusion', 'Countering misinformation & disinformation'], true, 'organisation-logos/logos/dailyviz263.webp', '', '', '', 'published'),
  ('policy-action-initiative', 'Policy Action Initiative', 'Kenya', 'Eastern Africa', 'Cohort 1', 'Helps young people in Kenya''s Coast region participate in governance through research, digital literacy and policy advocacy.', 'Policy Action Initiative (PAI) is a youth-led community-based organization that champions meaningful engagement of young people in governance and sustainable development in Kenya. We combine research, policy advocacy, and community-driven innovation to strengthen democratic participation, particularly among youth in rural communities in the Coast region. In our previous work, we have trained youth in digital literacy and civic engagement, and established community-based digital monitoring systems. We have also conducted nationwide research studies assessing the predictors of youth engagement in electoral processes and developed policy tools, including the National Roadmap on Countering Electoral Disinformation and localized visual guides on identifying misinformation online.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Electoral integrity & voter education', 'Countering misinformation & disinformation', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/policy-action-initiative.webp', '', '', '', 'published'),
  ('digital-woman-uganda', 'Digital Woman Uganda', 'Uganda', 'Eastern Africa', 'Cohort 1', 'Uses mobile and IVR technology, digital skills and support services to advance women''s safety, rights and digital inclusion in Uganda.', 'Digital Woman Uganda is a civic-tech organization dedicated to advancing digital inclusion, gender justice, and women’s empowerment through technology. We design and deploy innovative solutions—such as mobile and IVR platforms—to expand access to critical information, particularly on Gender-Based Violence (GBV), for women and girls in underserved and rural communities. Our work combines digital skills training, entrepreneurship support, and civic participation to enable women to safely engage in the digital space. Having reached over 23,000 women across Uganda, we continue to bridge the gap between technology and access, ensuring no woman is left behind in the digital age.', 'Collaboration interests have not yet been confirmed.', array['Digital rights', 'Digital safety & online security', 'Access to information & digital inclusion', 'Gender justice & technology'], true, 'organisation-logos/logos/digital-woman-uganda.webp', 'organisation-photos/profiles/digital-woman-uganda-community.webp', 'Digital Woman Uganda participants at a programme event.', '', 'published'),
  ('policy-lab-for-civic-innovation-and-community-solutions-politicos', 'Policy Lab for Civic Innovation and Community Solutions (POLITICOS)', 'Cameroon', 'Central Africa', 'Cohort 1', 'Uses research, civic education and participatory governance to strengthen accountability and citizen engagement in Cameroon.', 'POLITICOS is a problem-solving think tank operating at the intersection of civic innovation, research, and participatory governance in Cameroon. Founded in 2019, the organization generates evidence-based knowledge, strengthens accountability systems, and designs citizen-centered solutions to complex governance challenges.

Our work focuses on civic education, political participation, legislative engagement, voter education, community dialogue, policy advocacy, and local governance and decentralization to strengthen democratic practice at all levels. Through these interventions, POLITICOS promotes transparency, inclusion, and responsive public institutions, bridging the gap between citizens and state institutions by combining research, civic technology, and participatory approaches to governance.
', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Transparency & open data', 'Access to information & digital inclusion', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/policy-lab-for-civic-innovation-and-community-solutions-politicos.jpg', '', '', '', 'published'),
  ('factcheckafrica', 'FactCheckAfrica', 'Nigeria', 'West Africa', 'Cohort 1', 'Uses AI-assisted verification and media literacy to counter misinformation and support informed civic participation across Africa.', 'FactCheckAfrica is a fact-checking, AI research and digital rights organisation  dedicated to verifying news, combating misinformation, and promoting evidence-based civic engagement. Originally established as FactCheckElections in 2022, we evolved into a regional leader in AI-driven verification, monitoring political, social, and policy developments, translating complex information into accessible formats for citizens. We developed MyAIFactChecker, Africa’s first AI-powered fact-checking tool. Through digital tools, community outreach, and media partnerships, we empower individuals, especially marginalized and non-literate populations to make informed decisions, strengthen democratic processes, and hold institutions accountable. Our work bridges digital literacy gaps and fosters a culture of transparency and trust in public information.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Transparency & open data', 'Electoral integrity & voter education', 'Countering misinformation & disinformation', 'Access to information & digital inclusion', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/factcheckafrica.webp', '', '', '', 'published'),
  ('empowering-women-and-children-initiative', 'Empowering Women and Children Initiative', 'Nigeria', 'West Africa', 'Cohort 1', 'Uses community-centred digital tools and data training to connect rural women and youth to governance and public accountability in Nigeria.', 'The Empowering Women and Children Initiative (EWCI) is revolutionizing civic participation in Africa by bridging the gap between grassroots advocacy and digital governance. We deploy hyper-local digital ecosystems that empower marginalized women and youth to influence policy in real-time.
Using AI-driven interfaces and blockchain-enabled tools, we bypass connectivity barriers to ensure rural voices are authenticated in national agendas. Through our "Digital Literacy for Democracy" program, we train leaders to use data visualization to track government spending and service delivery. By converting lived experiences into actionable data, EWCI is architecting a transparent, bottom-up digital democracy where technology acts as the ultimate equalizer for social justice.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Digital rights', 'Digital safety & online security', 'Access to information & digital inclusion', 'Gender justice & technology', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/empowering-women-and-children-initiative.webp', '', '', '', 'published'),
  ('pulsivahub', 'PulsivaHub', 'South Africa', 'Southern Africa', 'Cohort 1', 'Develops AI tools that help people verify media, understand constitutional rights and engage more confidently in democracy.', 'PulsivaHub is an AI-powered civic companion project that aims to support African citizens to participate more meaningfully in democratic life by addressing the spread of misinformation and civic education through AI-enabled media verification and civic companion tools.
The Media Verifier puts verification tools directly in citizens'' hands, moving beyond reliance on content watermarking to enable citizens to check content for themselves. Our Civic Companions walk users through constitutional rights and responsibilities with a dedicated youth mode for ages 13 to 17. Constitution queries pull from the Constitute Project API. We are preparing a Cape Town pilot, building out WhatsApp-enabled civic querying to meet citizens where they already are.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Countering misinformation & disinformation', 'Access to information & digital inclusion', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/pulsivahub.webp', '', '', '', 'published'),
  ('gateway-to-elation', 'Gateway to Elation', 'Zimbabwe', 'Southern Africa', 'Cohort 1', 'Builds accessible digital skills and platforms so blind and visually impaired Zimbabweans can access information and participate fully.', 'Gateway to Elation empowers blind and visually impaired individuals to actively participate in society through accessible digital tools and skills. We support people to access information, express their views, and engage in decisions that affect their lives—areas where they are often excluded. Using screen-reader-friendly platforms, training, and community support, we turn everyday technology into a pathway for voice, independence, and inclusion. Our work focuses on practical impact: helping blind individuals connect, contribute, and be heard in civic and economic spaces, ensuring they are not left out of the digital and democratic landscape.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Digital rights', 'Digital safety & online security', 'Countering misinformation & disinformation', 'Access to information & digital inclusion', 'Youth civic engagement & digital technology', 'Intersectional disability inclusion'], true, 'organisation-logos/logos/gateway-to-elation.webp', '', '', '', 'published'),
  ('safe-haven-foundation-shf', 'Safe Haven Foundation-SHF', 'Cameroon', 'Central Africa', 'Cohort 1', 'Supports survivors of gender-based violence in Cameroon through trauma-informed care, advocacy and digital safety programmes.', 'Safe Haven Foundation is a youth-led, women-led, and survivor-led organisation in Cameroon working at the intersection of gender-based violence (GBV), mental health, and digital inclusion. We support young women, survivors, and marginalised communities through trauma-informed psychosocial care, survivor-centred advocacy, and digital capacity-building. Our work enables individuals not only to heal, but to safely access and participate in digital spaces where civic engagement and community decisions increasingly take place. Through community programmes and advocacy, we strengthen digital safety, amplify marginalised voices, and promote inclusive participation in civic and digital ecosystems.
', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Digital rights', 'Digital safety & online security', 'Access to information & digital inclusion', 'Gender justice & technology', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/safe-haven-foundation-shf.webp', '', '', '', 'published'),
  ('grace-agbonlahor-foundation', 'Grace Agbonlahor Foundation', 'Nigeria', 'West Africa', 'Cohort 1', 'Creates civic and leadership opportunities for girls and young women in Nigeria through programmes such as Voices at the Table.', 'The Grace Agbonlahor Foundation (GAF) is a youth- and women-focused nonprofit organisation advancing inclusive civic participation, economic empowerment, and social equity in Nigeria. We design and implement community-based programmes that equip girls and young women with the skills, confidence, and platforms to influence decisions that affect their lives. Our work spans civic engagement, education, and community development, with a focus on amplifying underserved voices and strengthening agency. Through initiatives such as Voices at the Table, we create accessible spaces for participation and dialogue, ensuring that grassroots perspectives inform community and policy conversations.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Gender justice & technology', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/grace-agbonlahor-foundation.webp', '', '', '', 'published'),
  ('safebangle-technologies', 'SafeBangle Technologies', 'Uganda', 'Eastern Africa', 'Cohort 1', 'Develops wearable and digital tools that help women and girls report gender-based violence and improve community safety in Uganda.', 'SafeBangle Technologies is a Ugandan civic-tech social enterprise working at the intersection of gender justice, digital rights, and community accountability. We design and deploy affordable wearable technology enabling women and girls in marginalised communities to report Gender-Based Violence in real time, even without internet access. Our SafeBangle bracelet sends instant SMS alerts with the user''s location to trusted contacts and authorities. Beyond the device, we operate a web-based incident management system that aggregates community safety data to support advocacy, accountability, and policy engagement. We have partnered with Makerere University (USAID-funded research), Somero Uganda, KCCA, and the Ministry of Gender to translate technology into civic impact. Registered in Uganda since 2019 and World Summit Awards (WSA)2024 Winner.', 'Collaboration interests have not yet been confirmed.', array['Digital rights', 'Digital safety & online security', 'Gender justice & technology'], true, 'organisation-logos/logos/safebangle-technologies.jpg', '', '', '', 'published'),
  ('jamaa-grands-lacs-citizen-voice-lab', 'JAMAA GRANDS LACS / CITIZEN VOICE LAB', 'Democratic Republic of the Congo', 'Central Africa', 'Cohort 1', 'Promotes peace, social cohesion and participatory democracy in the Great Lakes region through civic education, dialogue and digital platforms.', 'Our organization, JAMAA Grands Lacs, works to promote social cohesion, peaceful coexistence, and participatory democracy in the Great Lakes region. Through our Citizen University program, we build the capacity of citizens—particularly young people and marginalized communities—to actively participate in public life. We have also established the Citizen Voice Lab platform, which promotes citizen expression, inclusive dialogue, and accountability. Our work includes facilitating inter-community dialogue, supporting local leadership, and building resilience in the face of conflict and misinformation, while also using digital tools to amplify local voices.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Transparency & open data', 'Access to information & digital inclusion', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/jamaa-grands-lacs-citizen-voice-lab.webp', '', '', '#0b2f2e', 'published'),
  ('greenlenszw', 'Greenlenszw', 'Zimbabwe', 'Southern Africa', 'Cohort 1', 'Uses environmental journalism, photography and green media to make climate action visible and locally relevant in Zimbabwe.', 'Green Lens ZW is a Harare-based media initiative working across environmental journalism, photography and digital storytelling. It documents environmental issues and community responses while using green media to make climate action more visible, accessible and locally relevant. Its work helps audiences understand environmental challenges and the people responding to them.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Access to information & digital inclusion'], true, 'organisation-logos/logos/greenlenszw.jpg', '', '', '', 'published'),
  ('malawian-national-youth-in-politics', 'Malawian National Youth in Politics', 'Malawi', 'Southern Africa', 'Cohort 1', 'Trains young Malawians in leadership, governance and civic engagement so they can shape decisions and public accountability.', 'Malawian National Youth In Politics is a youth-led organisation dedicated to shaping the next generation of leaders in Malawi. We equip young people with leadership, governance, and civic engagement skills through training programs, mentorship, and practical exposure to political and community processes. Our work focuses on empowering youth to actively participate in decision-making, promote accountability, and contribute to sustainable national development. We particularly support young people from underserved communities to build confidence, competence, and a strong sense of responsibility in public leadership.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Transparency & open data', 'Access to information & digital inclusion', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/malawian-national-youth-in-politics.png', '', '', '', 'published'),
  ('legis360-centre-for-advocacy-development-and-public-enlightenment-initiatives', 'Legis360 Centre for Advocacy, Development and Public Enlightenment Initiatives', 'Nigeria', 'West Africa', 'Cohort 1', 'Uses AI to simplify legislation and help Nigerians follow, understand and engage with parliamentary processes.', 'Legis360 is a Nigerian civic technology organisation that uses artificial intelligence to make legislative processes accessible to citizens, civil society, and researchers. Our platform digitises bills, motions, and parliamentary activity from national and state assemblies, then transforms dense legal texts into plain-language summaries that ordinary people can understand and act on. We equip CSOs, journalists, youth advocates, and marginalised communities with real-time legislative alerts, legislator outreach tools, and advocacy dashboards, so that those most affected by laws have the information and tools to engage with the people making them. Our work sits at the intersection of digital rights, open governance, and civic participation.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Transparency & open data', 'Access to information & digital inclusion', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/legis360-centre-for-advocacy-development-and-public-enlightenment-initiatives.svg', '', '', '', 'published'),
  ('the-demography-project', 'The Demography Project', 'Kenya', 'Eastern Africa', 'Cohort 1', 'Combines civic technology, citizen science and journalism to make environmental data useful for inclusive public decision-making in Kenya.', 'The Demography Project is an independent youth-led non-profit organization that leverages artificial intelligence, civic technology, citizen science, community engagement, environmental education and grassroots journalism to empower water-scarce, climate-vulnerable & politically-disenfranchised individuals, households and communities in Kenya with actionable insights for inclusive participatory environmental democracy.

It is duly registered in Kenya as a community-based non-profit organization under the Community Groups Registration Act No. 30 of 2022 and is currently undergoing Equivalency Determination as a US charity. ', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Transparency & open data', 'Access to information & digital inclusion', 'Gender justice & technology', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/the-demography-project.webp', '', '', '', 'published'),
  ('nest-africa-artificial-intelligence-innovation-lab', 'Nest Africa Artificial Intelligence Innovation Lab', 'Nigeria', 'West Africa', 'Cohort 1', 'Turns climate data into accessible, local-language insights via mobile and USSD to support inclusive environmental decisions in Nigeria.', 'Nest Africa is a climate technology organization building AI-driven tools that improve access to information and support inclusive decision-making in underserved communities. Through solutions like AyeMọlẹ AI, we translate complex climate data into simple, localized, and multilingual insights accessible via mobile and USSD. We combine technology with community engagement, enabling citizens to understand climate risks, contribute local knowledge, and participate more effectively in decisions that affect their livelihoods. Our work addresses information inequality and strengthens data-driven, citizen-centered climate governance.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Transparency & open data', 'Access to information & digital inclusion'], true, 'organisation-logos/logos/nest-africa-artificial-intelligence-innovation-lab.png', '', '', '', 'published'),
  ('the-people-s-parliament', 'The People''s Parliament', 'Cameroon', 'Central Africa', 'Cohort 1', 'Makes parliamentary information easier to follow and gives Cameroonians more ways to engage with legislation and their representatives.', 'The People’s Parliament is a civic initiative in Cameroon focused on strengthening parliamentary transparency, accountability, and citizen engagement. Our core work involves making legislative processes more accessible by simplifying parliamentary information, tracking key activities such as bills and debates, and creating platforms for citizens to engage with their representatives.

We combine civic education, research, and digital tools to bridge the gap between Parliament and citizens, enabling more informed participation in democratic processes. Through public dialogue and citizen-focused initiatives, we support greater inclusion of youth, women, and marginalized groups in parliamentary engagement.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Transparency & open data', 'Access to information & digital inclusion', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/the-people-s-parliament.jpg', '', '', '', 'published'),
  ('open-knowledge-development-initiative', 'Open Knowledge Development Initiative', 'Nigeria', 'West Africa', 'Cohort 1', 'Strengthens digital rights, civic participation and open governance in Nigeria through research, technology and community programmes.', 'Open Knowledge Development Initiative is a nonprofit organisation working at the intersection of civic engagement, digital democracy, open knowledge, digital rights, and community empowerment in Nigeria. Our work focuses on strengthening citizen participation, digital rights, transparency, and accountability by equipping communities and civil society actors with knowledge, tools, and innovative approaches for social change. We design and implement programmes on civic technology, data-driven advocacy, gender inclusion, and freedom of information.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Transparency & open data', 'Electoral integrity & voter education', 'Access to information & digital inclusion', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/open-knowledge-development-initiative.webp', '', '', '', 'published'),
  ('tlakuka-creations-pty-ltd-trading-as-royal-bookstore', 'Tlakuka Creations Pty Ltd trading as Royal Bookstore', 'South Africa', 'Southern Africa', 'Cohort 1', 'Uses books, storytelling and skills programmes to promote literacy, preserve cultural narratives and expand creative opportunities in South Africa.', 'Royal Bookstore is a South African-based creative and literary organisation dedicated to publishing, storytelling, and community development. It supports emerging writers and creatives by providing platforms for writing, publishing, and skills development. Through books, workshops, and youth empowerment programmes, the organisation promotes literacy, preserves cultural narratives, and addresses social issues such as gender-based violence and mental health. Royal Bookstore also runs initiatives focused on work readiness and entrepreneurship, equipping young people with practical skills and opportunities to participate in the creative economy.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Transparency & open data', 'Digital rights', 'Digital safety & online security', 'Countering misinformation & disinformation', 'Access to information & digital inclusion', 'Gender justice & technology', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/tlakuka-creations-pty-ltd-trading-as-royal-bookstore.jpg', '', '', '', 'published'),
  ('the-uganda-minority-shelters-consortium-umsc', 'The Uganda Minority Shelters Consortium (UMSC)', 'Uganda', 'Eastern Africa', 'Cohort 1', 'Coordinates LGBTQI+ shelters and grassroots partners in Uganda, combining emergency support with digital safety and resilience work.', 'The Uganda Minority Shelters Consortium (UMSC) is a frontline umbrella network coordinating over 25 grassroots organizations. We provide life-saving support—including emergency housing, healthcare referrals, and legal aid—to LGBTQI+ individuals facing severe marginalization. While our historical focus has been physical sanctuary, the rapidly shifting technological landscape has forced an evolution in our mandate. We are increasingly focused on countering sophisticated digital threats, such as AI-driven extortion, digital entrapment, and targeted social media doxxing. UMSC is dedicated to building holistic community resilience, ensuring marginalized human rights defenders have both the physical safety and the encrypted digital tools necessary to survive and organize under oppressive regimes. ', 'Collaboration interests have not yet been confirmed.', array['Digital rights', 'Digital safety & online security'], true, 'organisation-logos/logos/the-uganda-minority-shelters-consortium-umsc.webp', '', '', '', 'published'),
  ('safe-her-clinic', 'Safe Her Clinic', 'Nigeria', 'West Africa', 'Cohort 1', 'Provides specialist digital safety and redress support to survivors of technology-facilitated gender-based violence in Nigeria.', 'Safe Her Clinic (SHC) is a for women, by women specialist digital safety clinic supporting survivors of gender-based violence who face technology-facilitated abuse. Our work is grounded in direct service delivery: by working with real survivors, in real communities, our vision is to build a trust infrastructure that allows women seek redress for TFGBV. 

', 'Collaboration interests have not yet been confirmed.', array['Digital rights', 'Digital safety & online security', 'Gender justice & technology'], true, 'organisation-logos/logos/safe-her-clinic.webp', '', '', '', 'published'),
  ('women-s-love-initiative-woli', 'Women''s Love Initiative-WOLI', 'Uganda', 'Eastern Africa', 'Cohort 1', 'Supports women and girls affected by violence in Uganda through advocacy, legal awareness, counselling and community-led prevention.', 'Women’s Love Initiative works to end violence against women and girls through community advocacy, legal awareness, psychosocial support, and empowerment programs. The organization supports survivors, engages communities to challenge harmful norms, and builds skills for women and girls in slum and rural areas to promote safety, dignity, and long-term resilience.
', 'Collaboration interests have not yet been confirmed.', array['Gender justice & technology'], true, 'organisation-logos/logos/women-s-love-initiative-woli.webp', '', '', '', 'published'),
  ('yandytech-community-ytc', 'YandyTech Community (YTC)', 'Nigeria', 'West Africa', 'Cohort 1', 'Builds digital skills, entrepreneurship and peaceful civic participation for youth, women and people with disabilities in Nigeria.', 'YandyTech Community (YTC) is a youth-led, nonprofit organisation in Nigeria advancing inclusive development through tech-driven community action. We strengthen pathways that help underserved people—especially youth, women and persons with disabilities—move from learning to earning and participate safely in civic life. Our work spans employability and entrepreneurship through the Decent Work & Entrepreneurship Lab (DWELab), digital skills and innovation pathways through SolutionLab, and peacebuilding/digital resilience through Tech4Peace & Citizen Lab (T4PCLab). We deliver community-rooted training, mentorship and incubation, develop civic-tech tools that counter misinformation and expand civic engagement, and convene partners across government, private sector and civil society to scale impact and strengthen systems.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Electoral integrity & voter education', 'Digital rights', 'Digital safety & online security', 'Countering misinformation & disinformation', 'Youth civic engagement & digital technology', 'Intersectional disability inclusion'], true, 'organisation-logos/logos/yandytech-community-ytc.webp', '', '', '', 'published'),
  ('smart-aid-initiative', 'Smart Aid Initiative', 'Nigeria', 'West Africa', 'Cohort 1', 'Expands education, digital inclusion and civic participation for women, girls, youth and people with disabilities in northern Nigeria.', 'Smart Aid Initiative is a youth-led nonprofit working to expand inclusive education, gender justice, digital inclusion, and civic participation for underserved communities in northern Nigeria. We design practical, community-rooted programmes that help women, girls, young people, and persons with disabilities access knowledge, opportunity, and decision-making spaces. Our work combines training, safeguarding, digital literacy, advocacy, and partnerships with institutions and communities to address exclusion. We have experience delivering programmes on girls’ rights, education access, ethical technology, and digital empowerment, with a strong focus on making tools, information, and public participation more accessible to those often left out.', 'Collaboration interests have not yet been confirmed.', array['Digital civic participation & citizen engagement', 'Digital rights', 'Digital safety & online security', 'Countering misinformation & disinformation', 'Access to information & digital inclusion', 'Gender justice & technology', 'Intersectional disability inclusion'], true, 'organisation-logos/logos/smart-aid-initiative.webp', '', '', '', 'published'),
  ('youth-initiative-for-drugs-research-support-information-and-education-youthrise-nigeria', 'YOUTH INITIATIVE FOR DRUGS RESEARCH SUPPORT INFORMATION AND EDUCATION (YOUTHRISE NIGERIA)', 'Nigeria', 'West Africa', 'Cohort 1', 'Advances health, rights and social justice for young Nigerians, including people who use drugs and other vulnerable groups.', 'YouthRISE Nigeria is an advocacy and service-based organization dedicated to promoting human rights, equitable health access, and socioeconomic justice for young people, including those who use drugs and other vulnerable populations.
YouthRISE Nigeria works and empowers young people through a multi-faceted approach that includes advocacy and community engagement for HIV prevention, treatment and care; SRHR programming; mental health and psychosocial counseling and support; provision of drug-related services; youth empowerment and development programs; maternal and child health; violence against women prevention and management; and partnership with Government and other stakeholders for policy reform, youth inclusion and participation, program implementation, and research.', 'Collaboration interests have not yet been confirmed.', array['Electoral integrity & voter education', 'Countering misinformation & disinformation', 'Youth civic engagement & digital technology'], true, 'organisation-logos/logos/youth-initiative-for-drugs-research-support-information-and-education-youthrise-nigeria.webp', '', '', '', 'published')
on conflict (slug) do update set
  name = excluded.name,
  country = excluded.country,
  region = excluded.region,
  cohort = excluded.cohort,
  summary = excluded.summary,
  description = excluded.description,
  collaboration = excluded.collaboration,
  focus_areas = excluded.focus_areas,
  matched = excluded.matched,
  logo_path = excluded.logo_path,
  photo_path = excluded.photo_path,
  photo_alt = excluded.photo_alt,
  logo_background = excluded.logo_background,
  publication_status = excluded.publication_status,
  updated_at = now();

